from openpyxl import load_workbook

wb = load_workbook('gdp.xlsx')

# Read Data sheet
data = wb['Data']
print("=== DATA SHEET ===")
print(f"Dimensions: {data.dimensions}")
# Print rows 1 to 5 to see header structure
print("\n--- Header rows ---")
for row in data.iter_rows(min_row=1, max_row=5, max_col=20, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {repr(cell.value)}")

# Print rows 20 to 42 to see the data range
print("\n--- Data rows 20-42 ---")
for row in data.iter_rows(min_row=20, max_row=42, max_col=20, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {repr(cell.value)}")
